mapper.select:
SELECT 
FROM sleep_log
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND biz_date = #{bizDate}
  AND is_deleted = 0
ORDER BY CASE WHEN segment = 'MAIN' THEN 0 ELSE 1 END, gmt_created ASC

SELECT 
FROM sleep_log
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND biz_date = #{bizDate}
  AND is_deleted = 0
  AND (segment = 'MAIN' OR segment IS NULL OR segment = '')
ORDER BY gmt_created ASC
LIMIT 1

SELECT 
FROM sleep_log
WHERE tenant_id = #{tenantId}
  AND people_id = #{peopleId}
  AND biz_date >= #{from}
  AND biz_date <= #{to}
  AND is_deleted = 0
ORDER BY biz_date ASC, CASE WHEN segment = 'MAIN' THEN 0 ELSE 1 END, gmt_created ASC
